+/**
+ * jOOQ queries behind the veterinarians grid of UC-002.
+ */
+@Repository
+@Transactional(readOnly = true)
+public class VetRepository {
+
+    private final DSLContext dsl;
+
+    public VetRepository(DSLContext dsl) {
+        this.dsl = dsl;
+    }
+
+    /**
+     * One page of vets, each with its specialties loaded in the same query
+     * and ordered alphabetically by name (BR-002). The vets themselves are
+     * ordered by last name, first name, and id, so pages never overlap.
+     */
+    public Stream<Vet> findPage(int offset, int limit) {
+        return dsl.select(
+                        VETS.ID, VETS.FIRST_NAME, VETS.LAST_NAME,
+                        multiset(
+                                select(SPECIALTIES.ID, SPECIALTIES.NAME)
+                                        .from(VET_SPECIALTIES)
+                                        .join(SPECIALTIES).on(SPECIALTIES.ID.eq(VET_SPECIALTIES.SPECIALTY_ID))
+                                        .where(VET_SPECIALTIES.VET_ID.eq(VETS.ID))
+                                        .orderBy(SPECIALTIES.NAME.asc()))
+                                .convertFrom(specialties -> specialties.map(mapping(Specialty::new))))
+                .from(VETS)
+                .orderBy(VETS.LAST_NAME.asc(), VETS.FIRST_NAME.asc(), VETS.ID.asc())
+                .offset(offset)
+                .limit(limit)
+                .fetch(mapping(Vet::new))
+                .stream();
+    }
+
+    public int count() {
+        return dsl.fetchCount(VETS);
+    }
+}
