+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.core.ui.MainLayout;
+import ai.unifiedprocess.petclinic.vet.domain.Specialty;
+import ai.unifiedprocess.petclinic.vet.domain.Vet;
+import ai.unifiedprocess.petclinic.vet.domain.VetRepository;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H2;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.router.BeforeEnterEvent;
+import com.vaadin.flow.router.BeforeEnterObserver;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+
+import java.util.stream.Collectors;
+
+/**
+ * UC-002: View Veterinarians.
+ *
+ * Lists every vet with first name, last name, and a comma-separated list of
+ * specialties ("none" if they hold none). The grid loads lazily as the user
+ * scrolls (BR-001) through a callback data provider backed by
+ * {@link VetRepository}.
+ */
+@Route(value = "vets", layout = MainLayout.class)
+@PageTitle("Veterinarians")
+public class VetsView extends VerticalLayout implements BeforeEnterObserver {
+
+    private final transient VetRepository vetRepository;
+
+    public VetsView(VetRepository vetRepository) {
+        this.vetRepository = vetRepository;
+        setSizeFull();
+
+        Grid<Vet> grid = new Grid<>();
+        grid.addColumn(Vet::firstName).setHeader("First Name");
+        grid.addColumn(Vet::lastName).setHeader("Last Name");
+        grid.addColumn(VetsView::specialties).setHeader("Specialties");
+        grid.setItems(
+                query -> this.vetRepository.findPage(query.getOffset(), query.getLimit()),
+                query -> this.vetRepository.count());
+        grid.setSizeFull();
+
+        add(new H2("Veterinarians"), grid);
+    }
+
+    /**
+     * The grid fetches only once the response is written, where a failure no
+     * longer reaches the router. Counting here lets a data-access error surface
+     * during navigation, so the application error view is shown instead of the
+     * grid (failure postcondition).
+     */
+    @Override
+    public void beforeEnter(BeforeEnterEvent event) {
+        vetRepository.count();
+    }
+
+    private static String specialties(Vet vet) {
+        if (vet.specialties().isEmpty()) {
+            return "none";
+        }
+        return vet.specialties().stream().map(Specialty::name).collect(Collectors.joining(", "));
+    }
+}
